SELECT s.interval_code, s.market_regime, s.decision, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, ROUND(SUM(p.realized_pnl), 4) AS pnl, ROUND(SUM(p.entry_price * p.quantity), 2) AS notional FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') GROUP BY s.interval_code, s.market_regime, s.decision ORDER BY s.interval_code, s.market_regime, s.decision LIMIT 40;